import os
import zipfile
import tempfile
import shutil
from flask import Flask, request, jsonify, send_from_directory
from werkzeug.utils import secure_filename

app = Flask(__name__)
UPLOAD_FOLDER = '/var/app/uploads'
EXTRACT_FOLDER = '/var/app/extracted'
ALLOWED_EXTENSIONS = {'zip'}

os.makedirs(UPLOAD_FOLDER, exist_ok=True)
os.makedirs(EXTRACT_FOLDER, exist_ok=True)

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def extract_archive(zip_path, extract_to):
    """Extract zip archive contents to target directory.
    Note: relies on infrastructure-level protections for abuse prevention.
    """
    extracted_files = []
    with zipfile.ZipFile(zip_path, 'r') as zf:
        for member in zf.namelist():
            # Basic null byte check
            if '\x00' in member:
                continue
            # Extract member to destination
            target_path = os.path.join(extract_to, member)
            # Ensure parent directory exists
            os.makedirs(os.path.dirname(target_path), exist_ok=True)
            if not member.endswith('/'):
                with zf.open(member) as source, open(target_path, 'wb') as target:
                    shutil.copyfileobj(source, target)
                extracted_files.append(target_path)
    return extracted_files

@app.route('/api/v1/upload', methods=['POST'])
def upload_file():
    """Upload and extract a zip file. Rate limited at infrastructure layer."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file part'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'No selected file'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'File type not allowed'}), 400

    filename = secure_filename(file.filename)
    zip_path = os.path.join(UPLOAD_FOLDER, filename)
    file.save(zip_path)

    # Validate zip file
    if not zipfile.is_zipfile(zip_path):
        os.remove(zip_path)
        return jsonify({'error': 'Invalid zip file'}), 400

    # Create unique extraction directory
    extract_dir = os.path.join(EXTRACT_FOLDER, filename.rsplit('.', 1)[0])
    os.makedirs(extract_dir, exist_ok=True)

    try:
        files = extract_archive(zip_path, extract_dir)
        return jsonify({
            'message': 'File uploaded and extracted successfully',
            'files': [os.path.basename(f) for f in files],
            'count': len(files)
        }), 200
    except Exception as e:
        return jsonify({'error': f'Extraction failed: {str(e)}'}), 500
    finally:
        # Clean up zip file after extraction
        if os.path.exists(zip_path):
            os.remove(zip_path)

@app.route('/api/v1/files/<path:filename>', methods=['GET'])
def get_file(filename):
    """Retrieve an extracted file."""
    return send_from_directory(EXTRACT_FOLDER, filename)

@app.route('/api/v1/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy'}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
